def format_json(model, result, seed:)
  last_point = result.coverage_curve.last
  payload = { "meta" => { "model_name" => model.model_name, "strength" => model.strength, "test_count" => result.rows.length, "exhaustive_count" => model.exhaustive_count, "reduction" => reduction_label(model.exhaustive_count, result.rows.length), "coverage" => if last_point
    format("%.1f%%", last_point.cumulative_pct)
  else
    "0.0%"
  end, "seed" => seed }, "coverage_curve" => result.coverage_curve.map { |point|
    { "scenario" => point.scenario, "cumulative_pct" => point.cumulative_pct }
  }, "scenarios" => named_rows(model, result).each_with_index.map { |row, index|
    { "id" => index + 1, "values" => nil }
  } }
  JSON.pretty_generate(payload, ascii_only: true)
end

